#!/usr/bin/env bash
# GENERATED BY AI
# Creates (or updates) the patient-demo-secrets Secret from the local .env.
# Values never touch the disk or git: the generated YAML goes straight into kubectl apply.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
ENV_FILE="$ROOT/.env"
[ -f "$ENV_FILE" ] || { echo "Missing $ENV_FILE: copy .env.example to .env and fill it in" >&2; exit 1; }

# .env may have Windows line endings: strip \r, or every value gets an invisible trailing \r
set -a; source <(tr -d '\r' < "$ENV_FILE"); set +a

# fail fast with a clear message, like ${VAR:?} in compose
: "${POSTGRES_PASSWORD:?missing in .env}"
: "${REF_DATA_CLIENT_SECRET:?missing in .env}"
: "${REF_DATA_ADMIN_CLIENT_SECRET:?missing in .env}"
: "${KEYCLOAK_ADMIN_PASSWORD:?missing in .env}"

kubectl create secret generic patient-demo-secrets \
  --namespace patient-demo \
  --from-literal=DB_PASSWORD="$POSTGRES_PASSWORD" \
  --from-literal=REF_DATA_CLIENT_SECRET="$REF_DATA_CLIENT_SECRET" \
  --from-literal=REF_DATA_ADMIN_CLIENT_SECRET="$REF_DATA_ADMIN_CLIENT_SECRET" \
  --from-literal=KEYCLOAK_ADMIN_PASSWORD="$KEYCLOAK_ADMIN_PASSWORD" \
  --dry-run=client -o yaml | kubectl apply -f -